// @ts-check
/**
 * overview-plus – configurable Overview dashboard strategy for Home Assistant.
 *
 *   strategy:
 *     type: custom:overview-plus
 *     card_rules: [...]        # see card-factory.js
 *     area_overrides: {...}    # see views/area-view.js
 *
 * Views generated by Overview Plus itself: one per area (custom:overview-plus-area).
 * Not yet re-implemented and therefore delegated to the built-in strategies:
 * overview page, media players, other devices. Card rules do not apply there yet.
 */

import { t } from "./i18n.js";
import { generateAreaView } from "./views/area-view.js";
import { LAZY_TYPE, lazifyView } from "./lazy-card.js";

export const VERSION = "0.0.0";

const LOG = "[overview-plus]";

/** Keys handled by Overview Plus; everything else is passed to the built-in overview view. */
const OWN_KEYS = ["type", "card_rules", "area_overrides", "load_home_settings", "strip_area_names", "lazy_render", "debug"];

/** @type {readonly string[]} */
const REGISTRY_DEPS = ["entities", "devices", "areas", "floors", "labels", "panels"];

/**
 * Settings of the built-in Overview (favorites, shortcuts, alerts), stored by HA as system data.
 * @param {any} hass
 */
async function loadHomeSettings(hass) {
  /** @param {string} key */
  const get = async (key) => {
    try {
      const res = await hass.callWS({ type: "frontend/get_system_data", key });
      return res?.value ?? {};
    } catch (err) {
      console.warn(`${LOG} System data "${key}" not readable.`, err);
      return {};
    }
  };
  const [home, security] = await Promise.all([get("home"), get("security")]);
  const settings = {
    alert_entities: security.alert_entities,
    favorite_entities: home.favorite_entities,
    hide_welcome_message: home.hide_welcome_message,
    hide_suggested_entities: home.hide_suggested_entities,
    shortcuts: home.shortcuts,
  };
  return Object.fromEntries(Object.entries(settings).filter(([, v]) => v !== undefined));
}

/**
 * @param {string} title
 * @param {unknown} err
 */
const errorView = (title, err) => ({
  type: "panel",
  cards: [{ type: "markdown", content: `**${title}**\n\n\`${String(/** @type {any} */ (err)?.message ?? err)}\`` }],
});

/**
 * Number of cards in a generated view, by type.
 * @param {any} view
 */
function cardStats(view) {
  /** @type {Record<string, number>} */
  const byType = {};
  let total = 0;
  let lazy = 0;
  for (const section of view.sections || [{ cards: view.cards || [] }]) {
    for (const card of section.cards || []) {
      if (card.type === "heading") continue;
      const type = card.type === LAZY_TYPE ? card.card?.type : card.type;
      byType[type] = (byType[type] || 0) + 1;
      total++;
      if (card.type === LAZY_TYPE) lazy++;
    }
  }
  return { total, lazy, byType };
}

/**
 * Debug: time from generating the view until the browser has painted it
 * (two animation frames after the cards were created, measured from `start`).
 * @param {string} area
 * @param {number} start
 */
function measureRender(area, start) {
  if (typeof requestAnimationFrame !== "function") return;
  let lastCount = -1;
  let stable = 0;
  const tick = () => {
    // The view is rendered once the number of card elements stops growing
    const count = document.querySelector("home-assistant")?.shadowRoot ? countCards() : 0;
    stable = count === lastCount ? stable + 1 : 0;
    lastCount = count;
    if (stable >= 3 || performance.now() - start > 10000) {
      console.info(`${LOG} area view "${area}": visible after ${(performance.now() - start).toFixed(0)} ms (${count} card elements)`);
      return;
    }
    requestAnimationFrame(tick);
  };
  requestAnimationFrame(tick);
}

/** Count rendered card elements in the open view (walks shadow roots). */
function countCards() {
  let n = 0;
  /** @param {Element | ShadowRoot} node */
  const walk = (node) => {
    node.querySelectorAll("*").forEach((el) => {
      if (el.localName.startsWith("hui-") && el.localName.endsWith("-card")) n++;
      if (el.shadowRoot) walk(el.shadowRoot);
    });
  };
  const root = document.querySelector("home-assistant")?.shadowRoot;
  if (root) walk(root);
  return n;
}

/** @param {any} oldHass @param {any} newHass */
const registryChanged = (oldHass, newHass) => REGISTRY_DEPS.some((k) => oldHass[k] !== newHass[k]);

class OverviewPlusDashboardStrategy {
  /**
   * @param {Record<string, any>} config
   * @param {any} hass
   */
  static async generate(config, hass) {
    if (hass.config?.state === "NOT_RUNNING") {
      return { views: [{ type: "sections", sections: [{ cards: [{ type: "starting" }] }] }] };
    }
    if (hass.config?.recovery_mode) {
      return { views: [{ type: "sections", sections: [{ cards: [{ type: "recovery-mode" }] }] }] };
    }

    const passthrough = Object.fromEntries(Object.entries(config).filter(([k]) => !OWN_KEYS.includes(k)));
    const overviewConfig =
      config.load_home_settings === false ? passthrough : { ...(await loadHomeSettings(hass)), ...passthrough };
    const overrides = config.area_overrides || {};

    const areaViews = Object.values(hass.areas || {}).map((area) => ({
      title: area.name,
      path: `areas-${area.area_id}`,
      subview: true,
      strategy: {
        type: "custom:overview-plus-area",
        area: area.area_id,
        card_rules: config.card_rules,
        override: overrides[area.area_id],
        strip_area_names: config.strip_area_names,
        lazy_render: config.lazy_render,
        debug: config.debug,
      },
    }));

    for (const id of Object.keys(overrides)) {
      if (!hass.areas?.[id]) console.warn(`${LOG} area_overrides: unknown area id "${id}".`);
    }

    return {
      views: [
        { icon: "mdi:home", path: "overview", strategy: { ...overviewConfig, type: "home-overview" } },
        ...areaViews,
        {
          title: t(hass, "media_players"),
          path: "media-players",
          subview: true,
          icon: "mdi:multimedia",
          strategy: { type: "home-media-players" },
        },
        {
          title: t(hass, "devices"),
          path: "other-devices",
          subview: true,
          icon: "mdi:devices",
          strategy: { type: "home-other-devices" },
        },
      ],
    };
  }

  static registryDependencies = ["areas"];

  /** Visual editor shown in the dashboard's edit dialog. */
  static async getConfigElement() {
    // Loaded lazily: the editor is only needed in the dashboard's edit dialog.
    const { ensureHaForm, EDITOR_TAG } = await import("./editor/editor.js");
    if (!(await ensureHaForm())) {
      console.warn(`${LOG} Form components not available – falling back to the YAML editor.`);
      return undefined;
    }
    return document.createElement(EDITOR_TAG);
  }

  /**
   * Suggested title and icon in the "new dashboard" dialog.
   * @param {any} hass
   */
  static getCreateSuggestions(hass) {
    return { title: t(hass, "dashboard_title"), icon: "mdi:home-plus" };
  }
}

class OverviewPlusAreaViewStrategy {
  /**
   * @param {Record<string, any>} config
   * @param {any} hass
   */
  static async generate(config, hass) {
    try {
      const start = performance.now();
      const generated = generateAreaView(hass, config.area, {
        card_rules: config.card_rules,
        override: config.override,
        strip_area_names: config.strip_area_names,
      });
      const report = generated.report;
      // Cards below the first screen are rendered when they scroll into view
      const view = config.lazy_render === false ? generated.view : lazifyView(generated.view);
      if (config.debug) {
        const ms = (performance.now() - start).toFixed(1);
        const stats = cardStats(view);
        const top = Object.entries(stats.byType).sort((a, b) => b[1] - a[1]).map(([k, n]) => `${n}× ${k}`).join(", ");
        console.groupCollapsed(`${LOG} area view "${config.area}": generated in ${ms} ms, ${stats.total} cards (${top}), ${stats.lazy} rendered on scroll`);
        console.log("report", report);
        console.log("view", view);
        console.groupEnd();
        measureRender(config.area, start);
      }
      return view;
    } catch (err) {
      console.error(`${LOG} Area view "${config.area}" failed.`, err);
      return errorView(t(hass, "error_title"), err);
    }
  }

  /** @param {any} _config @param {any} oldHass @param {any} newHass */
  static shouldRegenerate(_config, oldHass, newHass) {
    return registryChanged(oldHass, newHass);
  }
}

/** @type {[string, any][]} */
const ELEMENTS = [
  ["ll-strategy-dashboard-overview-plus", OverviewPlusDashboardStrategy],
  ["ll-strategy-view-overview-plus-area", OverviewPlusAreaViewStrategy],
];
for (const [tag, cls] of ELEMENTS) {
  if (!customElements.get(tag)) customElements.define(tag, cls);
}

// List the dashboard under "Community dashboards" in the "new dashboard" dialog
// (see home-assistant/frontend src/data/lovelace_custom_strategies.ts).
const registry = /** @type {any} */ (window);
registry.customStrategies = registry.customStrategies || [];
if (!registry.customStrategies.some((/** @type {any} */ s) => s.type === "overview-plus" && s.strategyType === "dashboard")) {
  registry.customStrategies.push({
    type: "overview-plus",
    strategyType: "dashboard",
    name: "Overview Plus",
    description: "The Overview dashboard with configurable cards and area layouts.",
    documentationURL: "https://github.com/financelurker/ha-overview-plus",
  });
}
console.info(`${LOG} ${VERSION} loaded`);
